ALTER TABLE library_ai_zone_candidates_v2 ADD COLUMN IF NOT EXISTS final_decision TEXT;
ALTER TABLE library_ai_zone_candidates_v2 ADD COLUMN IF NOT EXISTS final_decision_reason TEXT;
ALTER TABLE library_ai_zone_candidates_v2 ADD COLUMN IF NOT EXISTS final_decision_at TIMESTAMPTZ;
ALTER TABLE library_ai_zone_candidates_v2 ADD COLUMN IF NOT EXISTS final_decision_run_id TEXT;
ALTER TABLE library_ai_zone_candidates_v2 ADD COLUMN IF NOT EXISTS archived_for_audit BOOLEAN NOT NULL DEFAULT false;
CREATE OR REPLACE VIEW library_lmii_page_final_status_v2 AS SELECT a.pdf_page_number AS pdf_page,coalesce(n.content_node_id is not null,false) AS has_text,coalesce(c.structural_status='blank_page',false) AS is_blank,c.document_part,c.structural_status,c.lesson_number,CASE WHEN c.structural_status='blank_page' THEN 'blank_page' WHEN c.document_part='appendix' THEN 'classified_appendix_diagram' WHEN c.lesson_number IS NOT NULL THEN 'classified_lesson_page' ELSE 'page_literal_only_unclassified' END AS final_page_status,coalesce(n.content_node_id is not null,false) AS searchable_by_page,coalesce(n.content_node_id is not null,false) AS searchable_by_literal FROM library_page_anchors_v2 a LEFT JOIN library_content_nodes_v2 n ON n.page_anchor_id=a.page_anchor_id AND n.metadata_json->>'source_run_id'='lmii_full_page_first_v1' LEFT JOIN library_page_structural_classifications_v2 c ON c.page_anchor_id=a.page_anchor_id AND c.source_run_id='lmii_structural_detector_local_titles_v1_20260714' WHERE a.edition_id='lmii_page_first_v1';
CREATE OR REPLACE VIEW library_lmii_search_ready_v2 AS SELECT n.content_node_id,a.pdf_page_number,a.printed_page_number,n.literal_text,n.normalized_text,c.document_part,c.structural_status,c.lesson_number,n.content_type,n.node_role,n.authority_level,n.marker_kind,n.marker_value,n.visible_note_number,n.link_status,n.review_status FROM library_content_nodes_v2 n JOIN library_page_anchors_v2 a ON a.page_anchor_id=n.page_anchor_id LEFT JOIN library_page_structural_classifications_v2 c ON c.page_anchor_id=a.page_anchor_id AND c.source_run_id='lmii_structural_detector_local_titles_v1_20260714' WHERE n.metadata_json->>'source_run_id'='lmii_full_page_first_v1';
